from common import *
import random
# ---------- Principal: minimización
L=Log('EN-02-principal','EN-02 · CA2 · Principal: minimización de datos al registrar conductor')
c=client(); r=login(c,'admin'); L('Login admin:',r.status_code)
dni=str(random.randint(10000000,99999999)); aud_a=int(psql('select count(*) from auditoria'))
busy=psql("select vehiculo_id from vehiculos limit 1")
u0=c.post('/api/admin/users',json={'name':'Conductor Prueba Previa','email':f'esc0{dni}@example.invalid','password':'Escenario_Prueba_2026!','role':'driver'}).json()['id']
r0=c.post('/api/v1/drivers',json={'usuario_id':u0,'nombre_completo':'Conductor Prueba Previa','dni':str(int(dni)-1),'licencia':'Q-PRUEBA-00','vehiculo_id':busy})
L('Hallazgo: alta con DNI nuevo y un vehículo que ya tiene conductor ->',r0.status_code,r0.json().get('detail'),'(el mensaje atribuye el conflicto al DNI; la causa es la restricción única del vehículo)')
psql(f"delete from auditoria where usuario_id='{u0}' or entidad_id::text='{u0}'"); psql(f"delete from usuarios where usuario_id='{u0}'")
v=c.post('/api/v1/vehicles',json={'placa':'ESC-001','capacidad_kg':800,'tipo_combustible':'GNV'})
L('POST /api/v1/vehicles (vehículo libre para la prueba) ->',v.status_code)
veh=v.json().get('vehiculo_id') or psql("select vehiculo_id from vehiculos where placa='ESC-001'")
u=c.post('/api/admin/users',json={'name':'Conductor Prueba Escenario','email':f'esc{dni}@example.invalid','password':'Escenario_Prueba_2026!','role':'driver'})
L('POST /api/admin/users (cuenta de conductor) ->',u.status_code,'| respuesta:',json.dumps({k:('<omitido>' if k in('email',) else v) for k,v in u.json().items()},ensure_ascii=False))
uid=u.json().get('id') or u.json().get('usuario_id') or psql(f"select usuario_id from usuarios where email='esc{dni}@example.invalid'")
L('Columnas de la tabla usuarios:',psql("select string_agg(column_name,', ' order by ordinal_position) from information_schema.columns where table_name='usuarios'"))
body={'usuario_id':uid,'nombre_completo':'Conductor Prueba Escenario','dni':dni,'licencia':'Q-PRUEBA-01','vehiculo_id':veh}
r=c.post('/api/v1/drivers',json=body); L('POST /api/v1/drivers ->',r.status_code); L('  Respuesta:',json.dumps(r.json(),ensure_ascii=False).replace(dni,'<DNI enviado>'))
cid=r.json().get('conductor_id')
L('Columnas de la tabla conductores:',psql("select string_agg(column_name,', ' order by ordinal_position) from information_schema.columns where table_name='conductores'"))
row=psql(f"select nombre_completo, dni, licencia, coalesce(telefono,'NULL'), estado from conductores where conductor_id='{cid}'")
L('Fila persistida (nombre|dni|licencia|telefono|estado):',row.replace(dni,'<DNI enviado>'))
L('Columnas de pedidos (datos del destinatario):',psql("select string_agg(column_name,', ' order by ordinal_position) from information_schema.columns where table_name='pedidos'"))
L('Eventos de auditoría nuevos durante las altas (vehículo, cuenta y conductor):',int(psql('select count(*) from auditoria'))-aud_a, '|', psql("select string_agg(accion||' '||entidad, '; ') from (select * from auditoria order by registrada_en desc limit 3) a"))
L('Lista de campos con justificación y revisión de privacidad documentadas: no existe en el repositorio.')
psql(f"delete from conductores where conductor_id='{cid}'"); psql(f"delete from sesiones where usuario_id='{uid}'"); psql(f"delete from auditoria where usuario_id='{uid}' or entidad_id::text in ('{uid}','{cid}')"); psql(f"delete from usuarios where usuario_id='{uid}'"); psql(f"delete from auditoria where entidad_id::text='{veh}'"); psql(f"delete from vehiculos where vehiculo_id='{veh}'"); L('Cuenta y conductor de prueba eliminados tras la verificación.')
L.save()
# ---------- Feliz: sesión, CSRF, logout
L=Log('EN-02-feliz','EN-02 · Soporte · Feliz: sesión, mutación con CSRF y cierre de sesión')
c=client(); r=login(c,'admin'); L('Login ->',r.status_code,'| Set-Cookie:',r.headers.get('set-cookie','').split(';',1)[0].split('=')[0]+'=<token>; '+'; '.join(p.strip() for p in r.headers.get('set-cookie','').split(';')[1:]))
tok=c.cookies.get('eco_session'); uadm=psql("select usuario_id from usuarios where email='admin@example.invalid'"); s0=psql(f"select count(*) from sesiones where usuario_id='{uadm}' and expira_en>now()")
p=c.get('/api/admin/parameters').json()
csrf=c.headers.pop('X-CSRF-Token')
r=c.put('/api/admin/parameters',json=p); L('PUT /api/admin/parameters sin X-CSRF-Token ->',r.status_code,r.json().get('detail'))
c.headers['X-CSRF-Token']='token-incorrecto'; r=c.put('/api/admin/parameters',json=p); L('PUT con CSRF incorrecto ->',r.status_code,r.json().get('detail'))
c.headers['X-CSRF-Token']=csrf; r=c.put('/api/admin/parameters',json=p); L('PUT con CSRF válido (mismos valores) ->',r.status_code)
r=c.delete('/api/session'); L('DELETE /api/session ->',r.status_code)
L('Sesiones vigentes del administrador en BD: antes del cierre',s0,'| después',psql(f"select count(*) from sesiones where usuario_id='{uadm}' and expira_en>now()"))
L('Nota: la cookie no lleva Secure porque el .env local usa SESSION_COOKIE_SECURE=false (HTTP sin TLS); sin esa variable es Secure por defecto (test_security_headers.py).')
d=httpx.Client(base_url=API,headers={'Origin':ORIGIN},cookies={'eco_session':tok}); r=d.get('/api/session'); L('Reutilizar el token después del cierre ->',r.status_code)
L.save()
# ---------- Infeliz: inyección SQL
L=Log('EN-02-infeliz','EN-02 · CA1 · Infeliz: intento de inyección SQL en la autenticación')
aud0=int(psql('select count(*) from auditoria'))
for payload in ["admin@example.invalid' OR '1'='1' --","' OR 1=1; DROP TABLE usuarios; --"]:
    cc=client(); r=cc.post('/api/session',json={'email':payload,'password':"x' OR '1'='1"})
    L(f'POST /api/session email={payload!r} ->',r.status_code,r.json().get('detail'),'| cookie emitida:', 'eco_session' in r.headers.get('set-cookie',''))
L('Tabla usuarios intacta:',psql('select count(*) from usuarios'),'usuarios')
L('Nuevos eventos en auditoria:',int(psql('select count(*) from auditoria'))-aud0)
L('Intentos registrados en intentos_sesion:',psql('select count(*) from intentos_sesion'))
L('Notificación al equipo de seguridad: no existe mecanismo en el código (sin integración de alertas).')
L.save()
